if (!$env.TRANSCRIBE_API_URL || !$env.TRANSCRIBE_API_KEY) return [{ json: { falha: 'transcricao_nao_configurada', _ctx: e._ctx } }];
return [{ json: { media_id: e.media_id, _ctx: e._ctx } }];

